def _defer_to_event_loop(fn):
    """Run ``fn`` on the next Qt event-loop turn.

    A single named seam so the deferral is (a) obvious at the call site and
    (b) monkeypatchable in Qt-free tests.  See the 2026-09-07 right-click
    crash fix in ``_make_subviewer_right_click_handler``.
    """
    from qtpy.QtCore import QTimer

    QTimer.singleShot(0, fn)



def _nav_has_row(nav, label_id) -> bool:
    """True when the navigator has a selectable table row for *label_id*.

    A navigator that exposes no table (or a table that cannot be read) counts
    as having the row, so the caller keeps its normal select path.
    """
    table = getattr(nav, "_table", None)
    if table is None:
        return True
    try:
        from qtpy.QtCore import Qt

        for r in range(table.rowCount()):
            item = table.item(r, 1)
            if item is None:
                continue
            d = item.data(Qt.UserRole)
            if d and d.get("label_id") == label_id:
                return True
        return False
    except Exception:
        return True


